    map['fecha_inicio'] = Variable<DateTime>(fechaInicio);
    if (!nullToAbsent || fechaUltimaOcurrenciaEmitida != null) {
      map['fecha_ultima_ocurrencia_emitida'] = Variable<DateTime>(
        fechaUltimaOcurrenciaEmitida,
      );
    }
    map['items'] = Variable<String>(items);
    map['tiene_efectivo'] = Variable<bool>(tieneEfectivo);
