class Pedido extends DataClass implements Insertable<Pedido> {
  final String id;
  final String negocioId;
  final String proveedorNombre;
  final String? proveedorId;
  final String estado;
  final String? nota;
  final String? creadoPor;
  final String? creadoPorNombre;
  final String? recepcionadoPor;
  final String? recepcionadoPorNombre;

  /// #273: cuándo y quién envió el pedido al proveedor.
  ///
  /// Hasta #273 este hecho no quedaba registrado en NINGÚN lado: el service
  /// escribía `estado = 'enviado'` y nada más. Va como columna de la fila y no
  /// como registro de auditoría a propósito: `registros_auditoria` SUBE y NO
  /// BAJA en el pull, así que una fila ahí sólo la vería el dispositivo que la
  /// generó, y la trazabilidad se mira desde cualquiera.
  ///
  /// `enviadoPorNombre` está denormalizado por el mismo motivo que
  /// `creadoPorNombre`: la app funciona offline y el UUID no se puede resolver
  /// contra una tabla que quizá no bajó.
  final DateTime? fechaEnvio;
  final String? enviadoPor;
  final String? enviadoPorNombre;
  final String items;
  final double? total;
  final bool tieneEfectivo;
  final String? alertas;

  /// HU-142: día en que se pide recibir la mercadería. NULL = sin fecha pedida
  /// (el campo es OPCIONAL). Es un día de calendario: se guarda a medianoche
  /// local y en Supabase es `date`, no `timestamptz`. Ver utils/fecha_recepcion.dart.
  final DateTime? fechaRecepcionSolicitada;

  /// HU-013: agenda que generó este pedido. NULL = pedido normal.
  ///
  /// Referencia LÓGICA a propósito (convención de [creadoPor]), NO `.references()`:
  ///  • cada tabla del pull tiene su try/catch aislado, así que con FK dura y
  ///    `PRAGMA foreign_keys = ON` un fallo al bajar `pedidos_recurrentes` haría
  ///    reventar TODOS los pedidos recurrentes al insertar, en silencio: se
  ///    perderían pedidos reales por una tabla de configuración caída;
  ///  • con `onDelete: setNull`, dar de baja la agenda le sacaría la marca de
  ///    "recurrente" a los pedidos YA recibidos del Historial y se perdería la
  ///    procedencia.
  final String? agendaId;
  final DateTime fechaCreacion;
  final DateTime fechaActualizacion;
  final String estadoSync;
  final int version;
  const Pedido({
    required this.id,
    required this.negocioId,
    required this.proveedorNombre,
    this.proveedorId,
    required this.estado,
    this.nota,
    this.creadoPor,
    this.creadoPorNombre,
    this.recepcionadoPor,
    this.recepcionadoPorNombre,
    this.fechaEnvio,
    this.enviadoPor,
    this.enviadoPorNombre,
    required this.items,
    this.total,
    required this.tieneEfectivo,
    this.alertas,
    this.fechaRecepcionSolicitada,
    this.agendaId,
    required this.fechaCreacion,
    required this.fechaActualizacion,
    required this.estadoSync,
    required this.version,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['negocio_id'] = Variable<String>(negocioId);
    map['proveedor_nombre'] = Variable<String>(proveedorNombre);
    if (!nullToAbsent || proveedorId != null) {
      map['proveedor_id'] = Variable<String>(proveedorId);
    }
    map['estado'] = Variable<String>(estado);
    if (!nullToAbsent || nota != null) {
      map['nota'] = Variable<String>(nota);
    }
    if (!nullToAbsent || creadoPor != null) {
      map['creado_por'] = Variable<String>(creadoPor);
    }
    if (!nullToAbsent || creadoPorNombre != null) {
      map['creado_por_nombre'] = Variable<String>(creadoPorNombre);
    }
    if (!nullToAbsent || recepcionadoPor != null) {
      map['recepcionado_por'] = Variable<String>(recepcionadoPor);
    }
    if (!nullToAbsent || recepcionadoPorNombre != null) {
      map['recepcionado_por_nombre'] = Variable<String>(recepcionadoPorNombre);
    }
    if (!nullToAbsent || fechaEnvio != null) {
      map['fecha_envio'] = Variable<DateTime>(fechaEnvio);
    }
    if (!nullToAbsent || enviadoPor != null) {
      map['enviado_por'] = Variable<String>(enviadoPor);
    }
    if (!nullToAbsent || enviadoPorNombre != null) {
      map['enviado_por_nombre'] = Variable<String>(enviadoPorNombre);
    }
    map['items'] = Variable<String>(items);
    if (!nullToAbsent || total != null) {
      map['total'] = Variable<double>(total);
    }
    map['tiene_efectivo'] = Variable<bool>(tieneEfectivo);
    if (!nullToAbsent || alertas != null) {
      map['alertas'] = Variable<String>(alertas);
    }
    if (!nullToAbsent || fechaRecepcionSolicitada != null) {
      map['fecha_recepcion_solicitada'] = Variable<DateTime>(
        fechaRecepcionSolicitada,
      );
    }
    if (!nullToAbsent || agendaId != null) {
      map['agenda_id'] = Variable<String>(agendaId);
    }
    map['fecha_creacion'] = Variable<DateTime>(fechaCreacion);
    map['fecha_actualizacion'] = Variable<DateTime>(fechaActualizacion);
    map['estado_sync'] = Variable<String>(estadoSync);
    map['version'] = Variable<int>(version);
    return map;
  }

