class FacturaItem extends DataClass implements Insertable<FacturaItem> {
  final String id;

  /// Tenant propio (HU-045): el aislamiento es directo y no transitivo vía la
  /// factura. Es el patrón de la casa y lo que el verificador de migraciones
  /// mira en `information_schema` para las tablas hijas.
  final String negocioId;
  final String facturaId;

  /// A qué insumo se le cargó este costo. Es el argumento con el que se llama a
  /// `ServicioPrecios.registrar`, así que sin él el renglón no costea nada.
  ///
  /// SIN `onDelete`: a diferencia de la factura —que sí puede arrastrar a sus
  /// renglones— un insumo que desaparece no puede llevarse el detalle de una
  /// factura ya emitida, ni dejarlo apuntando a la nada. Los insumos se archivan
  /// (`activo = false`), no se borran, justamente por esto.
  final String insumoId;

  /// Cuánto entró. Viene de la recepción y NO se edita al procesar: lo que se
  /// carga acá es el precio, no la cantidad.
  final double cantidad;

  /// Precio NETO de una unidad, sin IVA.
  final double netoUnitario;

  /// Alícuota en FRACCIÓN: 0.21 = 21%, 0.105 = 10.5%, 0 = exento.
  ///
  /// La escala está declarada igual de los dos lados a propósito. La columna
  /// vieja `historial_precios.iva_porcentaje` nació en fracción en Drift y en
  /// PORCENTAJE en Postgres (`DEFAULT 21.0`), y no explotó de casualidad: el
  /// cliente manda siempre el valor explícito. La migración de #229 corrige
  /// aquella y estrena ésta ya alineada.
  final double alicuota;
  final DateTime fechaCreacion;
  final String estadoSync;
  const FacturaItem({
    required this.id,
    required this.negocioId,
    required this.facturaId,
    required this.insumoId,
    required this.cantidad,
    required this.netoUnitario,
    required this.alicuota,
    required this.fechaCreacion,
    required this.estadoSync,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['negocio_id'] = Variable<String>(negocioId);
    map['factura_id'] = Variable<String>(facturaId);
    map['insumo_id'] = Variable<String>(insumoId);
    map['cantidad'] = Variable<double>(cantidad);
    map['neto_unitario'] = Variable<double>(netoUnitario);
    map['alicuota'] = Variable<double>(alicuota);
    map['fecha_creacion'] = Variable<DateTime>(fechaCreacion);
    map['estado_sync'] = Variable<String>(estadoSync);
    return map;
  }

  FacturaItemsCompanion toCompanion(bool nullToAbsent) {
    return FacturaItemsCompanion(
      id: Value(id),
      negocioId: Value(negocioId),
      facturaId: Value(facturaId),
      insumoId: Value(insumoId),
      cantidad: Value(cantidad),
      netoUnitario: Value(netoUnitario),
      alicuota: Value(alicuota),
      fechaCreacion: Value(fechaCreacion),
      estadoSync: Value(estadoSync),
    );
  }

  factory FacturaItem.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return FacturaItem(
      id: serializer.fromJson<String>(json['id']),
      negocioId: serializer.fromJson<String>(json['negocioId']),
      facturaId: serializer.fromJson<String>(json['facturaId']),
      insumoId: serializer.fromJson<String>(json['insumoId']),
      cantidad: serializer.fromJson<double>(json['cantidad']),
      netoUnitario: serializer.fromJson<double>(json['netoUnitario']),
      alicuota: serializer.fromJson<double>(json['alicuota']),
      fechaCreacion: serializer.fromJson<DateTime>(json['fechaCreacion']),
      estadoSync: serializer.fromJson<String>(json['estadoSync']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'negocioId': serializer.toJson<String>(negocioId),
      'facturaId': serializer.toJson<String>(facturaId),
      'insumoId': serializer.toJson<String>(insumoId),
      'cantidad': serializer.toJson<double>(cantidad),
      'netoUnitario': serializer.toJson<double>(netoUnitario),
      'alicuota': serializer.toJson<double>(alicuota),
      'fechaCreacion': serializer.toJson<DateTime>(fechaCreacion),
      'estadoSync': serializer.toJson<String>(estadoSync),
    };
  }

