  );
  FacturaItem copyWithCompanion(FacturaItemsCompanion data) {
    return FacturaItem(
      id: data.id.present ? data.id.value : this.id,
      negocioId: data.negocioId.present ? data.negocioId.value : this.negocioId,
      facturaId: data.facturaId.present ? data.facturaId.value : this.facturaId,
      insumoId: data.insumoId.present ? data.insumoId.value : this.insumoId,
      cantidad: data.cantidad.present ? data.cantidad.value : this.cantidad,
      netoUnitario: data.netoUnitario.present
          ? data.netoUnitario.value
          : this.netoUnitario,
      alicuota: data.alicuota.present ? data.alicuota.value : this.alicuota,
      fechaCreacion: data.fechaCreacion.present
          ? data.fechaCreacion.value
          : this.fechaCreacion,
      estadoSync: data.estadoSync.present
          ? data.estadoSync.value
          : this.estadoSync,
    );
  }

  @override
  String toString() {
    return (StringBuffer('FacturaItem(')
          ..write('id: $id, ')
          ..write('negocioId: $negocioId, ')
          ..write('facturaId: $facturaId, ')
          ..write('insumoId: $insumoId, ')
          ..write('cantidad: $cantidad, ')
          ..write('netoUnitario: $netoUnitario, ')
          ..write('alicuota: $alicuota, ')
          ..write('fechaCreacion: $fechaCreacion, ')
          ..write('estadoSync: $estadoSync')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    negocioId,
    facturaId,
    insumoId,
