    required this.categoria,
    this.tiempoElaboracionMinutos,
    this.imagenUrl,
    required this.archivada,
    required this.fechaCreacion,
    required this.fechaActualizacion,
    required this.estadoSync,
    required this.version,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['negocio_id'] = Variable<String>(negocioId);
    map['nombre'] = Variable<String>(nombre);
    map['porciones'] = Variable<double>(porciones);
    if (!nullToAbsent || precioVentaCarta != null) {
      map['precio_venta_carta'] = Variable<double>(precioVentaCarta);
    }
    if (!nullToAbsent || margenDeseadoPorcentaje != null) {
      map['margen_deseado_porcentaje'] = Variable<double>(
        margenDeseadoPorcentaje,
      );
    }
    map['categoria'] = Variable<String>(categoria);
    if (!nullToAbsent || tiempoElaboracionMinutos != null) {
      map['tiempo_elaboracion_minutos'] = Variable<double>(
        tiempoElaboracionMinutos,
      );
    }
    if (!nullToAbsent || imagenUrl != null) {
      map['imagen_url'] = Variable<String>(imagenUrl);
    }
    map['archivada'] = Variable<bool>(archivada);
    map['fecha_creacion'] = Variable<DateTime>(fechaCreacion);
    map['fecha_actualizacion'] = Variable<DateTime>(fechaActualizacion);
    map['estado_sync'] = Variable<String>(estadoSync);
    map['version'] = Variable<int>(version);
    return map;
  }

  RecetasCompanion toCompanion(bool nullToAbsent) {
    return RecetasCompanion(
      id: Value(id),
