class $$NegociosTableTableManager
    extends
        RootTableManager<
          _$BaseDatosApp,
          $NegociosTable,
          Negocio,
          $$NegociosTableFilterComposer,
          $$NegociosTableOrderingComposer,
          $$NegociosTableAnnotationComposer,
          $$NegociosTableCreateCompanionBuilder,
          $$NegociosTableUpdateCompanionBuilder,
          (Negocio, $$NegociosTableReferences),
          Negocio,
          PrefetchHooks Function({
            bool usuariosRefs,
            bool proveedoresRefs,
            bool categoriasRefs,
            bool insumosRefs,
            bool insumoProveedoresRefs,
            bool pedidosRecurrentesRefs,
            bool historialPreciosRefs,
            bool alertasDesviacionRefs,
            bool pedidosRefs,
            bool recepcionesRefs,
            bool motivosRecepcionRefs,
            bool proveedorCategoriasRefs,
            bool adjuntosRefs,
            bool facturasRefs,
            bool facturaItemsRefs,
            bool pagosRefs,
            bool imputacionesPagoRefs,
            bool anticiposRefs,
            bool movimientosCuentaCorrienteRefs,
            bool registrosAuditoriaRefs,
            bool configuracionNegocioRefs,
            bool recetasRefs,
            bool recetaIngredientesRefs,
          })
        > {
  $$NegociosTableTableManager(_$BaseDatosApp db, $NegociosTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$NegociosTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$NegociosTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$NegociosTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> nombre = const Value.absent(),
                Value<String> tipo = const Value.absent(),
                Value<String> pais = const Value.absent(),
                Value<String?> email = const Value.absent(),
                Value<DateTime> fechaCreacion = const Value.absent(),
                Value<DateTime> fechaActualizacion = const Value.absent(),
                Value<String> estadoSync = const Value.absent(),
                Value<int> version = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => NegociosCompanion(
                id: id,
                nombre: nombre,
                tipo: tipo,
                pais: pais,
                email: email,
                fechaCreacion: fechaCreacion,
                fechaActualizacion: fechaActualizacion,
                estadoSync: estadoSync,
                version: version,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String nombre,
                required String tipo,
                Value<String> pais = const Value.absent(),
                Value<String?> email = const Value.absent(),
                Value<DateTime> fechaCreacion = const Value.absent(),
                Value<DateTime> fechaActualizacion = const Value.absent(),
                Value<String> estadoSync = const Value.absent(),
                Value<int> version = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => NegociosCompanion.insert(
                id: id,
                nombre: nombre,
                tipo: tipo,
                pais: pais,
                email: email,
                fechaCreacion: fechaCreacion,
                fechaActualizacion: fechaActualizacion,
                estadoSync: estadoSync,
                version: version,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (
                  e.readTable(table),
                  $$NegociosTableReferences(db, table, e),
                ),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                usuariosRefs = false,
                proveedoresRefs = false,
                categoriasRefs = false,
                insumosRefs = false,
                insumoProveedoresRefs = false,
                pedidosRecurrentesRefs = false,
                historialPreciosRefs = false,
                alertasDesviacionRefs = false,
                pedidosRefs = false,
                recepcionesRefs = false,
                motivosRecepcionRefs = false,
                proveedorCategoriasRefs = false,
                adjuntosRefs = false,
                facturasRefs = false,
                facturaItemsRefs = false,
                pagosRefs = false,
                imputacionesPagoRefs = false,
                anticiposRefs = false,
                movimientosCuentaCorrienteRefs = false,
                registrosAuditoriaRefs = false,
                configuracionNegocioRefs = false,
                recetasRefs = false,
                recetaIngredientesRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (usuariosRefs) db.usuarios,
                    if (proveedoresRefs) db.proveedores,
                    if (categoriasRefs) db.categorias,
                    if (insumosRefs) db.insumos,
                    if (insumoProveedoresRefs) db.insumoProveedores,
                    if (pedidosRecurrentesRefs) db.pedidosRecurrentes,
                    if (historialPreciosRefs) db.historialPrecios,
                    if (alertasDesviacionRefs) db.alertasDesviacion,
                    if (pedidosRefs) db.pedidos,
                    if (recepcionesRefs) db.recepciones,
                    if (motivosRecepcionRefs) db.motivosRecepcion,
                    if (proveedorCategoriasRefs) db.proveedorCategorias,
                    if (adjuntosRefs) db.adjuntos,
                    if (facturasRefs) db.facturas,
                    if (facturaItemsRefs) db.facturaItems,
                    if (pagosRefs) db.pagos,
                    if (imputacionesPagoRefs) db.imputacionesPago,
                    if (anticiposRefs) db.anticipos,
                    if (movimientosCuentaCorrienteRefs)
                      db.movimientosCuentaCorriente,
                    if (registrosAuditoriaRefs) db.registrosAuditoria,
                    if (configuracionNegocioRefs) db.configuracionNegocio,
                    if (recetasRefs) db.recetas,
                    if (recetaIngredientesRefs) db.recetaIngredientes,
                  ],
                  addJoins: null,
                  getPrefetchedDataCallback: (items) async {
                    return [
                      if (usuariosRefs)
                        await $_getPrefetchedData<
                          Negocio,
                          $NegociosTable,
                          Usuario
                        >(
                          currentTable: table,
                          referencedTable: $$NegociosTableReferences
                              ._usuariosRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $$NegociosTableReferences(
                                db,
                                table,
                                p0,
                              ).usuariosRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.negocioId == item.id,
                              ),
